#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
const int MAX_STATE = (1 << 20) + 5;
int n, limit, result;
int power1[MAX_STATE], power2[MAX_STATE];
int constraints[10][10], values[10][10], tripleMask[10][10][10];

long long modPow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long x) {
    return modPow(x, MOD - 2);
}

bool isValid(int a, int b, int c) {
    int arr[3] = {a, b, c};
    int perm[3] = {0, 1, 2};
    do {
        if (constraints[arr[perm[0]]][1] && 
            constraints[arr[perm[1]]][2] && 
            constraints[arr[perm[2]]][3]) {
            return true;
        }
    } while (next_permutation(perm, perm + 3));
    return false;
}

void firstDFS(int coeff, int row, int col) {
    if (row == 7 && col == 1) {
        int state = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (isValid(i, j, k)) {
                        int x = 1;
                        while (x == i || x == j || x == k) x++;
                        int y = x + 1;
                        while (y == i || y == j || y == k) y++;
                        int z = y + 1;
                        while (z == i || z == j || z == k) z++;
                        state |= tripleMask[x][y][z];
                    }
                }
            }
        }
        power1[state] = (power1[state] + coeff) % MOD;
        return;
    }

    constraints[row][col] = 1;
    if (col == 3) 
        firstDFS((1LL * coeff * values[row][col]) % MOD, row + 1, 1);
    else 
        firstDFS((1LL * coeff * values[row][col]) % MOD, row, col + 1);
    constraints[row][col] = 0;

    if (col == 3) 
        firstDFS((1LL * coeff * (MOD + 1 - values[row][col])) % MOD, row + 1, 1);
    else 
        firstDFS((1LL * coeff * (MOD + 1 - values[row][col])) % MOD, row, col + 1);
}

void secondDFS(int coeff, int row, int col) {
    if (row == 7 && col == 4) {
        int state = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (isValid(i, j, k)) {
                        state |= tripleMask[i][j][k];
                    }
                }
            }
        }
        power2[state] = (power2[state] + coeff) % MOD;
        result = (result + 1LL * power1[limit ^ state] * coeff) % MOD;
        return;
    }

    constraints[row][col - 3] = 1;
    if (col == 6) 
        secondDFS((1LL * coeff * values[row][col]) % MOD, row + 1, 4);
    else 
        secondDFS((1LL * coeff * values[row][col]) % MOD, row, col + 1);
    constraints[row][col - 3] = 0;

    if (col == 6) 
        secondDFS((1LL * coeff * (MOD + 1 - values[row][col])) % MOD, row + 1, 4);
    else 
        secondDFS((1LL * coeff * (MOD + 1 - values[row][col])) % MOD, row, col + 1);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            int temp;
            scanf("%d", &temp);
            values[i][j] = (1LL * temp * modInverse(100)) % MOD;
        }
    }
    for (int i = n + 1; i <= 6; i++) {
        values[i][i] = 1;
    }

    int counter = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = i + 1; j <= 6; j++) {
            for (int k = j + 1; k <= 6; k++) {
                tripleMask[i][j][k] = 1 << counter++;
            }
        }
    }

    firstDFS(1, 1, 1);
    limit = (1 << 20) - 1;

    for (int bit = 0; bit < 20; bit++) {
        for (int state = 0; state <= limit; state++) {
            if (state >> bit & 1) {
                power1[state] = (power1[state] + power1[state ^ (1 << bit)]) % MOD;
            }
        }
    }

    secondDFS(1, 1, 4);
    result = (MOD + 1 - result) % MOD;
    printf("%d\n", result);
    return 0;
}
